var requestedProject = C8O.marketplace._trim(project);
if (!requestedProject.length) {
  throw new Error("project is required");
}
var importedName = C8O.marketplace._trim(importedProjectName);
var importErrorMessage = "";
try {
  marketplaceImportResult = C8O.marketplace.importLibrary({
    project: requestedProject,
    importedProjectName: importedName,
    save: true,
    forceImport: false
  });
} catch (importError) {
  importErrorMessage = String(importError);
  marketplaceImportResult = {
    status: "error",
    targetProject: "",
    library: requestedProject,
    technicalName: "",
    cloneUrl: "",
    branch: "",
    projectUrl: "",
    loadedBefore: false,
    loadedAfter: false,
    imported: false,
    importStatus: "failed",
    importMessage: importErrorMessage,
    addReference: false,
    referenceAlready: false,
    referenceAdded: false,
    referenceUpdated: false,
    referenceName: "",
    referenceProjectUrl: "",
    saveRequested: false,
    saved: false,
    saveMessage: "",
    refresh: false,
    warnings: [importErrorMessage]
  };
}
marketplaceImportRefresh = marketplaceImportResult && marketplaceImportResult.refresh === true;
marketplaceImportTargetQName = marketplaceImportResult && marketplaceImportResult.targetProject ? String(marketplaceImportResult.targetProject) : "";
marketplaceImportLibraryQName = marketplaceImportTargetQName;
marketplaceImportLoadedAfter = marketplaceImportResult && marketplaceImportResult.loadedAfter === true;
marketplaceImportTimestamp = java.lang.System.currentTimeMillis();

previousRefreshQNameDefined = typeof qname !== "undefined" && qname !== null;
if (previousRefreshQNameDefined) {
  previousRefreshQNameValue = qname;
} else {
  previousRefreshQNameValue = null;
}
qname = marketplaceImportTargetQName;

if (previousRefreshQNameDefined) {
  qname = previousRefreshQNameValue;
} else {
  try {
    delete qname;
  } catch (_ignoreDeleteQName) {
    qname = undefined;
  }
}
